def get_demo_pair(text, n):
 m=re.search(rf'Demo pair {n} input \((\d+)x(\d+)\):\n(.*?)\nDemo pair {n} output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance\.|\Z)',text,re.S)
 if not m: raise ValueError(f'no match {n}')
 h,w=map(int,m.group(1,2))
 def grid(s):
  rows=[[int(x) for x in ln.split()] for ln in s.strip().splitlines()]
  assert len(rows)==h and all(len(row)==w for row in rows),(len(rows),[len(r) for r in rows])
  return rows
 return grid(m.group(3)),grid(m.group(4))
